nta.system:
// Template instances
RequestProc = Request();
CoordinatorProc = Coordinator();

CaptureWorker = WorkerNode(NODE_CAPTURE, CAP_COMP_T);
PeerWorker = WorkerNode(NODE_PEER, PEER_COMP_T);
PeerWorker2 = WorkerNode(NODE_PEER2, PEER_COMP_T);
PeerWorker3 = WorkerNode(NODE_PEER3, PEER_COMP_T);
PeerWorker4 = WorkerNode(NODE_PEER4, PEER_COMP_T);
EdgeWorker = WorkerNode(NODE_EDGE, EDGE_COMP_T);

LinkCP = Link(LINK_CP, TX1_T);
LinkPE = Link(LINK_PE, TX2_T);
LinkCE = Link(LINK_CE, TXE_T);
LinkCP2 = Link(LINK_CP2, TX1_T);
LinkCP3 = Link(LINK_CP3, TX1_T);
LinkCP4 = Link(LINK_CP4, TX1_T);

MonitorProc = Monitor();
FailoverManagerProc = FailoverManager();

// System composition
system RequestProc, CoordinatorProc, CaptureWorker, PeerWorker, PeerWorker2, PeerWorker3, PeerWorker4, EdgeWorker, LinkCP, LinkPE, LinkCE, LinkCP2, LinkCP3, LinkCP4, MonitorProc, FailoverManagerProc;
